// Extract download link from email body
const items = $input.all();
const out = [];
for (const it of items) {
  const body = it.json.snippet + '\n' + (it.json.textPlain || '') + '\n' + (it.json.textHtml || '');
  // tune this regex to match your PGM email's link format
  const m = body.match(/https?:\/\/[^\s"'<>]+\.(xlsx?|XLSX?)(\?[^\s"'<>]*)?/);
  if (!m) {
    throw new Error('No XLS download link found in email ' + it.json.id);
  }
  out.push({ json: { emailId: it.json.id, downloadUrl: m[0] } });
}
return out;

// Normalize PGM columns -> our schema.
// Adjust the mapping to match the actual column headers in your PGM export.
const rows = $input.all();
const out = [];

const pick = (r, ...keys) => {
  for (const k of keys) {
    if (r[k] !== undefined && r[k] !== null && r[k] !== '') return r[k];
  }
  return null;
};

const parseDate = (v) => {
  if (!v) return null;
  if (v instanceof Date) return v.toISOString().slice(0,10);
  const s = String(v).trim();
  // Excel serial?
  if (/^\d+(\.\d+)?$/.test(s)) {
    const d = new Date((Number(s) - 25569) * 86400 * 1000);
    return d.toISOString().slice(0,10);
  }
  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0,10);
};

const parseNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[$,\s]/g,''));
  return isNaN(n) ? null : n;
};

for (const r of rows.map(x => x.json)) {
  const rec = {
    member_code:  pick(r, 'Member Code','MemberCode','Code','ID','Member ID'),
    name:         pick(r, 'Full Name','Name','Member Name'),
    phone:        pick(r, 'Phone','Mobile','Phone Number','Tel'),
    email:        pick(r, 'Email','E-mail'),
    gender:       pick(r, 'Gender','Sex'),
    dob:          parseDate(pick(r, 'DOB','Date of Birth','Birthday')),
    join_date:    parseDate(pick(r, 'Join Date','Joined','Registration Date')),
    plan_type:    pick(r, 'Plan','Membership Type','Contract Type','Product'),
    plan_start:   parseDate(pick(r, 'Plan Start','Contract Start','Start Date')),
    plan_end:     parseDate(pick(r, 'Plan End','Contract End','End Date','Expiry')),
    status:       pick(r, 'Status','Contract Status'),
    pt_sessions_left: parseNum(pick(r, 'PT Sessions Left','PT Remaining','Sessions Left')),
    last_visit:   parseDate(pick(r, 'Last Visit','Last Check-in')),
    total_paid:   parseNum(pick(r, 'Total Paid','Revenue','Amount Paid')),
    branch:       pick(r, 'Branch','Club','Location'),
    notes:        pick(r, 'Notes','Remarks'),
    raw_data:     r
  };
  if (!rec.member_code) continue; // skip rows without code
  out.push({ json: rec });
}
return out;
